<script setup lang="ts">import{onMounted,reactive,ref}from'vue';import{Page}from'@vben/common-ui';import{listPlatformPresellsApi,type PlatformPresell}from'#/api/core/platform-presell';const loading=ref(false),rows=ref<PlatformPresell[]>([]),total=ref(0),query=reactive({limit:20,mer_id:undefined as number|undefined,page:1});async function load(){loading.value=true;try{const d=await listPlatformPresellsApi(query);rows.value=d.list||[];total.value=d.total||0}finally{loading.value=false}}onMounted(()=>void load());</script><template><Page title="预售监管" description="监管商户预售活动；当前为真实只读列表，修改与删除等待平台独立权限开放。"><el-card shadow="never"><el-form inline><el-form-item label="商户 ID"><el-input-number v-model="query.mer_id" :min="1"/></el-form-item><el-button type="primary" @click="query.page=1;load()">查询</el-button></el-form><el-table v-loading="loading" :data="rows"><el-table-column label="预售商品" min-width="180" prop="store_name"/><el-table-column label="商户" min-width="130"><template #default="{row}">{{row.mer_name||`商户 #${row.mer_id}`}}</template></el-table-column><el-table-column label="预售价" width="110"><template #default="{row}">¥{{Number(row.price).toFixed(2)}}</template></el-table-column><el-table-column label="时间" min-width="220"><template #default="{row}">{{row.start_time}} 至 {{row.end_time}}</template></el-table-column><el-table-column label="状态" width="90"><template #default="{row}"><el-tag :type="row.status===1?'success':'info'">{{row.status===1?'启用':'停用'}}</el-tag></template></el-table-column></el-table><div class="mt-4 flex justify-end"><el-pagination :current-page="query.page" :page-size="query.limit" :total="total" layout="total, prev, pager, next" @current-change="p=>{query.page=p;load()}"/></div></el-card></Page></template>
